-- Seed 32 listing demo; rerunnable by deterministic slug.
on conflict (slug) do update set subdistrict_name=excluded.subdistrict_name, regency_name=excluded.regency_name, property_type=excluded.property_type, condition=excluded.condition, furnishing=excluded.furnishing, can_kpr=excluded.can_kpr, is_lelang=excluded.is_lelang, lelang_type=excluded.lelang_type, takeover_status=excluded.takeover_status, certificate_type=excluded.certificate_type, images=excluded.images, status=excluded.status, published_at=excluded.published_at;
